-- ComsFlow v2: run ONLY in project lyeyjfvxmqruszgfrjze SQL Editor.
-- Generated by npm run db:sql; no passwords, keys, users or old data included.
-- Installs schema + private bucket. Does NOT copy Railway data or create an admin.
-- Entire installation rolls back on error. Reruns verify migration checksums.
BEGIN;
SET LOCAL search_path=public,extensions;
SELECT pg_advisory_xact_lock(742917);
DO $target_guard$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND tablename<>'schema_migrations') THEN
  IF to_regclass('public.schema_migrations') IS NULL THEN
   RAISE EXCEPTION 'This is not an empty ComsFlow project. Stop: select the NEW Supabase project.';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.schema_migrations WHERE name='001_initial.sql') THEN
   RAISE EXCEPTION 'Existing tables do not belong to this installer. Stop and verify target.';
  END IF;
 END IF;
END
$target_guard$;
CREATE TABLE IF NOT EXISTS public.schema_migrations(name text PRIMARY KEY,checksum text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.schema_migrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.schema_migrations FROM PUBLIC;
DO $migration_permissions$
DECLARE role_name text;
BEGIN
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON public.schema_migrations FROM %I',role_name); END IF;
 END LOOP;
END
$migration_permissions$;

